CREATE OR REPLACE FUNCTION brand_policy_reason(brand text, name text, poi_id text, manual text, poi_type text, codes text, raw jsonb) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
 WITH evidence AS MATERIALIZED (SELECT (CASE brand WHEN '吖嘀吖嘀' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(吖嘀吖嘀)','\1') WHEN '好想来' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(好想来|好想来品牌零食|好想来零食乐园|好想来全食优选)','\1') WHEN '戴永红' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(戴永红)','\1') WHEN '来伊份' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(来伊份)','\1') WHEN '来优品' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(来优品|来优品品牌零食|来优品零食乐园)','\1') WHEN '爱零食' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(爱零食)','\1') WHEN '糖巢' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(糖巢)','\1') WHEN '老婆大人' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(老婆大人)','\1') WHEN '赵一鸣零食' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(赵一鸣零食|赵一鸣省钱超市)','\1') WHEN '陆小馋' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(陆小馋)','\1') WHEN '零食很忙' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(零食很忙)','\1') WHEN '零食悦' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(零食悦)','\1') WHEN '零食有鸣' THEN regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1'),'^(?:[一-龥]{1,12}(?:省|市|县|区|镇|乡|村)){1,3}(零食有鸣)','\1') ELSE regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ailingshi_normalize(name),'^([^()]+\([^()]+)\)([^()]+店)\)$','\1\2)'),'品牌品牌零食','品牌零食'),'省钱省钱超市','省钱超市'),'^([^()]+)\[省钱超市\]$','\1省钱超市'),'^([^()]+\([^()]+)[}〕］]$','\1)'),'^([^()]+\([^()]+)$','\1)'),'^([^()]+\([^()]+\))\)+$','\1'),'^([^()]+\([^()]+\))[^()]{1,30}(路|街|道|巷|弄)[0-9]+号?$','\1') END) AS n, ailingshi_normalize(name) AS source_name,
 COALESCE(poi_type,'') || ';' || COALESCE(raw->>'tag','') || ';' || COALESCE(raw#>>'{business,tag}','') || ';' || COALESCE(raw#>>'{business,rectag}','') || ';' || COALESCE(raw#>>'{business,keytag}','') AS tags,
 COALESCE(raw->>'tag','') || ';' || COALESCE(raw#>>'{business,tag}','') || ';' || COALESCE(raw#>>'{business,rectag}','') || ';' || COALESCE(raw#>>'{business,keytag}','') AS business_tags,
 COALESCE(poi_type,'') AS pt,
 regexp_replace(COALESCE(codes,''),'[[:space:]]','','g') AS c), flags AS (
 SELECT *, (tags ~ '零食|超市|购物' OR c ~ '(^|[|;,])06[0-9]{4}([|;,]|$)') AS retail,
 tags ~ '零食' AS snack_evidence,
 business_tags ~ '(^|[;,])零食([;,]|$)' AS business_snack,
 tags ~ '(^|[;,|])[[:space:]]*(零食|超市|综合超市|大型超市|折扣超市)[[:space:]]*([;,|]|$)' AS clear_retail FROM evidence)
 SELECT CASE
 WHEN btrim(COALESCE(poi_id,''))<>'' AND manual='exclude' THEN '按 POI ID 人工排除'
 WHEN source_name ~ '暂停营业|装修中|正在装修|装修店铺|停业|歇业|已关闭|未开业|即将开业|待开业|筹备中|施工中' THEN '标注暂停营业、装修中或未开业，非当前营业门店'
 WHEN n ~ '\([^()]*(仓库|仓)\)' THEN '名称明确为仓库，非营业门店'
 WHEN split_part(n,'(',1) ~ '蛋糕|糕饼|西饼|酱卤|卤味|卤菜|熟食|餐厅|餐馆|饭店|小吃|快餐|火锅|烧烤|麻辣烫|炸鸡|汉堡|奶茶|咖啡|面馆|浇面|米粉|足道|足疗|足浴|按摩|推拿|生鲜超市|酒店|宾馆|药房|药店|服装|理发|美容|公司$|仓库|配送中心|仓配中心|供应链中心|办事处|甜品|烘焙|民宿|公寓$|外卖柜|网吧|KTV|停车场|充电站|动物医院|物流基地|面试中心|菜鸟驿站|铁锅炖|农家饭馆|钓鱼|垂钓|钓场|台球(俱乐部|店)?$|棋牌(俱乐部|室)?$|洗衣(店)?$|果业$|眼镜店$|娱乐馆|资产$|控股集团|网络$|信息中心|种植场|冷冻大全|冰社$|家具|家纺|文具店|培训中心|旅馆|青年旅舍|客栈|家庭农场|骨科|运营中心|总部$|凉菜|把子肉|攀爬乐园|服饰鞋帽|煎饼|猪脚饭|游泳健身|烟酒|锅贴|老年俱乐部|茶馆|茶府|蒸包|鲜肉|果蔬|糖水|茶饮|饮品|冷饮|冰糖葫芦|居酒屋|餐酒馆|拖鞋|电子厂|清洁用品|鲜花店|加工厂|装修(店)?$|休闲娱乐馆|健康生活馆|仓储物流中心|仓储中心|物流中心|共配中心|营销中心|业务中心|收货区|食品包装|专业音响|音响设备|童装|内衣|饰界|五金|电脑|数码|烟花爆竹|代买|代购|仓$' OR (tags ~ '鞋店|金店|珠宝|服饰鞋包|内衣|童装|视听影音|数码|电脑销售|五金|礼品店' AND (CASE brand WHEN '吖嘀吖嘀' THEN (position('吖嘀吖嘀' in split_part(n,'(',1))=0 AND (position('吖嘀吖嘀' in n)>0)) WHEN '好想来' THEN (position('好想来' in split_part(n,'(',1))=0 AND position('好想来品牌零食' in split_part(n,'(',1))=0 AND position('好想来零食乐园' in split_part(n,'(',1))=0 AND position('好想来全食优选' in split_part(n,'(',1))=0 AND (position('好想来' in n)>0 OR position('好想来品牌零食' in n)>0 OR position('好想来零食乐园' in n)>0 OR position('好想来全食优选' in n)>0)) WHEN '戴永红' THEN (position('戴永红' in split_part(n,'(',1))=0 AND (position('戴永红' in n)>0)) WHEN '来伊份' THEN (position('来伊份' in split_part(n,'(',1))=0 AND (position('来伊份' in n)>0)) WHEN '来优品' THEN (position('来优品' in split_part(n,'(',1))=0 AND position('来优品品牌零食' in split_part(n,'(',1))=0 AND position('来优品零食乐园' in split_part(n,'(',1))=0 AND (position('来优品' in n)>0 OR position('来优品品牌零食' in n)>0 OR position('来优品零食乐园' in n)>0)) WHEN '爱零食' THEN (position('爱零食' in split_part(n,'(',1))=0 AND (position('爱零食' in n)>0)) WHEN '糖巢' THEN (position('糖巢' in split_part(n,'(',1))=0 AND (position('糖巢' in n)>0)) WHEN '老婆大人' THEN (position('老婆大人' in split_part(n,'(',1))=0 AND (position('老婆大人' in n)>0)) WHEN '赵一鸣零食' THEN (position('赵一鸣零食' in split_part(n,'(',1))=0 AND position('赵一鸣省钱超市' in split_part(n,'(',1))=0 AND (position('赵一鸣零食' in n)>0 OR position('赵一鸣省钱超市' in n)>0)) WHEN '陆小馋' THEN (position('陆小馋' in split_part(n,'(',1))=0 AND (position('陆小馋' in n)>0)) WHEN '零食很忙' THEN (position('零食很忙' in split_part(n,'(',1))=0 AND (position('零食很忙' in n)>0)) WHEN '零食悦' THEN (position('零食悦' in split_part(n,'(',1))=0 AND (position('零食悦' in n)>0)) WHEN '零食有鸣' THEN (position('零食有鸣' in split_part(n,'(',1))=0 AND (position('零食有鸣' in n)>0)) ELSE FALSE END)) OR n ~ '\([^()]*(办事处|营销中心|收货区|业务中心|仓储物流中心|运营中心|总部)\)' OR source_name ~ '\)[^()]*(停车场|自动售货机)$' THEN '名称主体明确为餐饮、足浴、生鲜、仓库等非目标业态'
 WHEN (brand='爱零食' AND split_part(n,'(',1) ~ '(^爱零食的喵|我爱零食|最爱零食|爱零食小屋|吾爱零食|嘴爱零食|唯爱零食|喜爱零食|久爱零食|伍爱零食|几分爱零食)') OR (brand='好想来' AND n ~ '^好像来') THEN '相似名称，不按目标品牌收录'
